pub fn ranked_labels(scores: &[i32]) -> Vec<String> {
    let mut result = Vec::new();
    let mut i = 0;
    while i < scores.len() {
        result.push(format!("{}: {}", i + 1, scores[i]));
        i += 1;
    }
    result
}

test_setup_files.tests/ranked_labels_test.rs:
use ranked_labels::ranked_labels;

#[test]
fn basic_ranking() {
    assert_eq!(
        ranked_labels(&[10, 20, 30]),
        vec!["1: 10".to_string(), "2: 20".to_string(), "3: 30".to_string()]
    );
}

#[test]
fn preserves_input_order_including_duplicates() {
    assert_eq!(
        ranked_labels(&[5, 5, 1]),
        vec!["1: 5".to_string(), "2: 5".to_string(), "3: 1".to_string()]
    );
}

#[test]
fn empty_slice_returns_empty_vec() {
    let empty: &[i32] = &[];
    assert_eq!(ranked_labels(empty), Vec::<String>::new());
}

#[test]
fn single_element() {
    assert_eq!(ranked_labels(&[42]), vec!["1: 42".to_string()]);
}

