// DRIFT: rank is now 0-based instead of 1-based.
pub fn ranked_labels(scores: &[i32]) -> Vec<String> {
    scores
        .iter()
        .enumerate()
        .map(|(i, score)| format!("{}: {}", i, score))
        .collect()
}
